// @ts-ignore Generated by `opennextjs-cloudflare build`
import openNextWorker from "./.open-next/worker.js";
import { HoopsLobby, HoopsRoom } from "./lib/hoopsRoomDO.ts";
import {
  handleCloudflareMultiplayerRequest,
  type CloudflareMultiplayerEnv,
} from "./lib/cloudflareMultiplayerRouter.ts";

export { HoopsRoom, HoopsLobby };

export interface Env extends CloudflareMultiplayerEnv {
  ASSETS?: Fetcher;
  WORKER_SELF_REFERENCE?: Fetcher;
}

const worker = {
  async fetch(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
    const url = new URL(request.url);

    if (url.pathname.startsWith("/ws/multiplayer") || url.pathname.startsWith("/api/multiplayer")) {
      const mpResponse = await handleCloudflareMultiplayerRequest(request, env);
      if (mpResponse) return mpResponse;
    }

    return openNextWorker.fetch(request, env as CloudflareEnv, ctx);
  },
};

export default worker;
